SELECT CASE WHEN c.credit_limit >= 14100 THEN 'high' WHEN c.credit_limit >= 2900 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.country, COUNT(CASE WHEN a.account_type = 'LOAN' THEN 1 END) AS loan_count FROM accounts a FULL OUTER JOIN customers c ON a.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 14100 THEN 'high' WHEN c.credit_limit >= 2900 THEN 'mid' ELSE 'low' END, c.country HAVING loan_count > 4
